import{c as t,Q as a,j as o,m as s}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"SkillCAT: Contrastive Assessment and Topology-Aware Skill Self-Evolution for LLM Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.13317","title":"SkillCAT: Contrastive Assessment and Topology-Aware Skill Self-Evolution for LLM Agents","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.13317,"authors":["Kunfeng Chen","Qihuang Zhong","Juhua Liu","Bo Du"],"domains":["cs.CL"],"html":"https://arxiv.org/html/2606.13317v1","pdf_path":"pdfs/2606.13317.pdf","published_date":"2026-06-11T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-11-skillcat-contrastive-topology-skill-evolution-2606-13317.md","filePath":"research/papers/2026-06-11-skillcat-contrastive-topology-skill-evolution-2606-13317.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-06-11-skillcat-contrastive-topology-skill-evolution-2606-13317.md"};function l(i,e,n,c,h,u){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="skillcat-contrastive-assessment-and-topology-aware-skill-self-evolution-for-llm-agents" tabindex="-1">SkillCAT: Contrastive Assessment and Topology-Aware Skill Self-Evolution for LLM Agents <a class="header-anchor" href="#skillcat-contrastive-assessment-and-topology-aware-skill-self-evolution-for-llm-agents" aria-label="Permalink to &quot;SkillCAT: Contrastive Assessment and Topology-Aware Skill Self-Evolution for LLM Agents&quot;">​</a></h1><p><strong>Authors</strong>: Kunfeng Chen, Qihuang Zhong, Juhua Liu, Bo Du <strong>Published</strong>: June 11, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.13317" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.13317</a> · <a href="https://arxiv.org/html/2606.13317v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.13317 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.13317" target="_blank" rel="noreferrer">research/papers/pdfs/2606.13317.pdf</a> (9 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Skill self-evolution methods for LLM agents aim to turn execution trajectories into reusable skill documents, but current pipelines typically learn from one trajectory per task, merge candidate skill patches before checking them, and load the full skill corpus before inference. We propose SkillCAT, a training-free framework that separates this process into three stages. Contrastive Causal Extraction (CCE) samples multiple trajectories for each task and compares same-task success/failure pairs to identify evidence that explains outcome differences. Assessment-Augmented Evolution (AAE) replays each candidate patch on source-task clones and keeps only patches that improve or preserve task outcomes before hierarchical skill patch merging. Topology-Aware Task Execution (TTE) compiles the evolved skills into a routable sub-skill topology, so inference loads only the capability nodes relevant to the task. We evaluate SkillCAT on common agent benchmarks, including SpreadsheetBench, WikiTableQuestions, and DocVQA, and further test cross-model and out-of-distribution generalization. Across these settings, SkillCAT raises the average score over baselines by up to 40.40%, demonstrating reliable skill evolution without model training.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><p>training-free 的 skill 自演化框架，修正現有三個缺陷（單 trajectory 學習 / patch 未驗先 merge / inference 載入全 corpus）。三階段：</p><ol><li><strong>CCE（Contrastive Causal Extraction）</strong> — 每任務多 trajectory，比對同任務 success/failure 配對，抽出「解釋成敗差異」的證據（非單軌）。</li><li><strong>AAE（Assessment-Augmented Evolution）</strong> — 每個候選 patch 在 source-task clone 上 replay，<strong>只保留改善或維持結果的 patch</strong> 才進階層式 merge（= 演化-後-驗證閘）。</li><li><strong>TTE（Topology-Aware Task Execution）</strong> — 演化後 skill 編成可路由的 sub-skill topology，inference 只載入相關 capability node（降 context）。</li></ol><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>跨 SpreadsheetBench / WikiTableQuestions / DocVQA，平均分數超基線 <strong>最多 +40.40%</strong>；含 cross-model 與 OOD 泛化。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>9 pp，benchmark 偏 document/table 任務；多 trajectory 取樣成本未量化。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接補 <code>skill-evolution</code> 的演化-後-驗證閉環</strong>：AAE「patch replay 只保留不回退者」= seesaw constraint 於 skill 層；對應 harness-synthesis 報告 T27（skill empirical eval gate）。</li><li><strong>TTE ↔ lazy-load</strong>：「只載相關 capability node」印證本 workspace skill lazy-load + 對應 SkillRAE 的 skill-graph 選擇性載入。</li><li><strong>CCE success/failure 對比</strong>：可作 <code>skill-evolution:scan</code> 的證據抽取方法參考（非只看單次成功）。</li><li>⚠️ 落地需多 trajectory + replay clone 基建，本 workspace 暫無自動 trajectory store（同 trace-pipeline 缺口）。</li></ul>',17)])])}const g=t(r,[["render",l]]);export{d as __pageData,g as default};
